    // Only set explicit inline height when the caller passes a specific value.
    // With the default '100%', CSS flex: 1 fills the parent — no inline style needed.
    const wrapperStyle =
        height !== "100%"
            ? { height: typeof height === "number" ? `${height}px` : height }
