        listRef.current
            ?.closest("[data-radix-scroll-area-viewport]")
            ?.scrollTo({ top: 0, behavior: reduce ? "auto" : "smooth" });

    const goTo = useCallback(
        (p: number) => {
            setPage(Math.max(1, Math.min(p, totalPages)));
            scrollTop();
