const EASE: [number, number, number, number] = [0.16, 1, 0.3, 1];

const stagger: Variants = {
    hidden: {},
    show: { transition: { staggerChildren: 0.05, delayChildren: 0.04 } },
};

const fadeUp: Variants = {
