};

// ─── Primitives ──────────────────────────────────────────────────────────────

function Eyebrow({ children }: { children: ReactNode }) {
    return (
        <span className="select-none font-mono text-[11px] uppercase tracking-[0.12em] text-zinc-500">
            {children}
        </span>
    );
}

function Kbd({ children }: { children: ReactNode }) {
