    useEffect(() => {
        const c = ref.current;
        const ctx = c?.getContext("2d");
        if (!c || !ctx) return;

        const reduce = prefersReducedMotion();
        let w = 0, h = 0, raf = 0, visible = true;
        let last = performance.now();
