            const ang = rand(0.3, 0.6);
            const sp = rand(9, 14);
            shooting.push({
                x: dir > 0 ? rand(-0.05 * w, 0.55 * w) : rand(0.45 * w, 1.05 * w),
                y: rand(-0.05 * h, 0.5 * h),
                vx: dir * Math.cos(ang) * sp,
                vy: Math.sin(ang) * sp,
                len: rand(90, 160),
                t: 0,
                max: rand(45, 80),
                accent: Math.random() < 0.3,
