@keyframes af-spin{to{transform:rotate(360deg)}}
@keyframes af-scroll{0%{transform:translateY(0);opacity:1}100%{transform:translateY(12px);opacity:0}}
.af-float{animation:af-float 5s ease-in-out infinite}
