    onClick: () => void;
}) => {
    return (
        <button
            type="button"
            onClick={onClick}
            aria-label={isOpen ? "Close menu" : "Open menu"}
            aria-expanded={isOpen}
            className="rounded-md p-1 text-black dark:text-white"
        >
            {isOpen ? <IconX aria-hidden /> : <IconMenu2 aria-hidden />}
        </button>
    );
};

