    };
    const draw = (scope: Element | null, at: number, span = D * 0.8) => {
      if (!scope) return;
      const body = Array.from(scope.querySelectorAll<SVGElement>('[data-draw="shaft"]'));
      const tips = Array.from(scope.querySelectorAll<SVGElement>('[data-draw="head"]'));
