      add(tips, { strokeDashoffset: [1, 0], duration: D * 0.25, ease: "outQuad" }, at + span * 0.85);
    };
    const reddenBox = (ts: HTMLElement[]) =>
      ts.forEach((g) => {
        const b = g.querySelector<HTMLElement>("[data-box]");
