      }
      case "markIn": {
        const m = el.querySelector<HTMLElement>(`[data-mark="${p.markId}"]`);
        if (m) {
          utils.set(m, { scale: 0.4, opacity: 0, y: -8 });
          add(m, { opacity: 1, duration: D * 0.3, ease: "outQuad" }, 0);
