    const { host, anim, reduced, finish, build, reveal } = o;
    const el = host.current;
    if (!el) return;
    const qa = <T extends Element>(sel: string) => Array.from(el.querySelectorAll<T>(sel));
    const items = qa<HTMLElement>("[data-item]");
