        const sel = t.querySelector<HTMLElement>("[data-sel]");
        if (sel) utils.set(sel, { scale: 1, opacity: 1 });
        const box = t.querySelector<HTMLElement>("[data-box]");
        if (box) box.style.borderColor = box.dataset.border ?? "";
