      for (const p of ptrEls) utils.set(p, { x: tx(p), y: ty(p), scale: 1, opacity: 1 });
      el.querySelectorAll("[data-ptr-pill]").forEach((e) => utils.set(e, { scale: 1 }));
      for (const g of edgeEls) {
