    const beforeEdges = prevEdges.current;
    for (const t of live) {
      const [sx, sy] = before.get(t.dataset.id!) ?? [tx(t), ty(t)];
      utils.set(t, { x: sx, y: sy });
    }
    for (const g of ghostItems) utils.set(g, { x: tx(g), y: ty(g) });
    for (const p of ptrEls) {
