      const playSteps = (list: Step[], at: number) => {
        list.forEach((st, i) => {
          const t = at + i * D;
          add(chips[i], { opacity: 1, scale: 1.04, duration: D * 0.25, ease: "outQuad" }, t);
          add(chips[i], { scale: 1, duration: D * 0.5, ease: soft }, t + D * 0.25);
