    });
  }
  let order = 0;
  for (const a of algorithms) {
    order += 1;
    const script = CATALOG_SCRIPTS[a.slug] ?? scripts[a.slug] ?? null;
    const fields = {
      name: a.name, description: a.description, categoryId: a.categoryId, difficulty: a.difficulty,
