  await prisma.auditLog.upsert({
    where: { id: "seed_audit_1" }, update: {},
    create: { id: "seed_audit_1", actorId: admin.id, action: "seed.data_created", targetType: "seed", targetId: null, meta: json({ source: "seed.ts" }) },
