  });

  console.log(`Seeded ${categories.length} categories, ${algorithms.length} algorithms and demo data for every Phase 5 model.`);
}

main()
  .catch((e) => { console.error(e); process.exitCode = 1; })
  .finally(() => prisma.$disconnect());

