});

export const AlgorithmDetailSchema = z.object({
  id: z.string(),
  slug: z.string(),
  name: z.string(),
  description: z.string(),
  difficulty: DifficultySchema,
  complexity: z
    .object({
      timeBest: z.string().nullable(),
      timeAverage: z.string().nullable(),
      timeWorst: z.string().nullable(),
      space: z.string().nullable(),
    })
    .nullable(),
