    readonly hiddenOps?: readonly string[];
    /** A new EMPTY structure. Scripts never depend on starter data. */
    create(): unknown;
}

export interface Diagnostic {
    severity: "error" | "warning" | "info";
    message: string;
    /** 1-based, matches Monaco. */
    line: number;
    column: number;
    endLine: number;
    endColumn: number;
