            if (V >= MAX_VERTICES) return reject(s, ran, `The lab limits the graph to ${MAX_VERTICES} vertices so it stays readable.`);
            let anchor: Vertex | undefined;
            if (op.attachTo !== undefined && op.attachTo !== "") {
