}

export interface InitEdge {
    from: number; // vertex INDEX (0-based), so duplicate labels are never ambiguous
    to: number;
    weight?: number;
}
export interface InitSpec {
    vertices: Primitive[];
    edges: InitEdge[];
}

export type GraphOp =
    | { type: "initialize"; data: InitSpec }
    | { type: "reset" }
    | { type: "setProps"; props: Partial<GraphProps> }
