        const n = (op as Extract<HashOp, { type: "initialize" }>).entries.length;
        return `initialize(${n} ${n === 1 ? "item" : "items"})`;
    }
    const args = Object.values(rest)
        .filter((v) => v !== undefined)
        .map((v) => JSON.stringify(v))
        .join(", ");
